async function call(path,data){const r=await fetch('/api/auth/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw Error(translateError(result.error)||t("We couldn't connect to the server.", "Không thể kết nối máy chủ.", "서버에 연결할 수 없습니다."));return result;}
